bool check(ll n){
	if(n<0)return false;
	if(n==0)return true;
	for(ll p=2;p*p<=n;p++)if(n%p==0){
		int e=0;
		while(n%p==0){
			n/=p;
			e++;
		}
		if(p%4==3&&e%2==1)return false;
	}
	return n%4!=3;
}


