#include <bits/stdc++.h>
using namespace std;

int main() {
    int N; cin >> N;
    vector<string> C(N);
    for (int i = 0; i < N; i++) cin >> C[i];

    // L[x][y] = (x,y) 左侧（含）o 的个数；R/U/D 同理
    vector<vector<long long>> L(N, vector<long long>(N, 0)), R(N, vector<long long>(N, 0)),
        U(N, vector<long long>(N, 0)), D(N, vector<long long>(N, 0));

    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            L[i][j] = (j > 0 ? L[i][j - 1] : 0) + (C[i][j] == 'o');
        }
        for (int j = N - 1; j >= 0; j--) {
            R[i][j] = (j + 1 < N ? R[i][j + 1] : 0) + (C[i][j] == 'o');
        }
    }
    for (int j = 0; j < N; j++) {
        for (int i = 0; i < N; i++) {
            U[i][j] = (i > 0 ? U[i - 1][j] : 0) + (C[i][j] == 'o');
        }
        for (int i = N - 1; i >= 0; i--) {
            D[i][j] = (i + 1 < N ? D[i + 1][j] : 0) + (C[i][j] == 'o');
        }
    }

    long long ans = 0;
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            if (C[i][j] != 'o') continue;
            // 自身也算在 L/R/U/D 里，L 形拐角外的两个端点从"剩余"里选：
            // (left-1)*(dn-1) + (dn-1)*(right-1) + (right-1)*(up-1) + (up-1)*(left-1)
            long long l = L[i][j] - 1, r = R[i][j] - 1, u = U[i][j] - 1, d = D[i][j] - 1;
            ans += l * d + d * r + r * u + u * l;
        }
    }
    cout << ans << '\n';
    return 0;
}

