#include <bits/stdc++.h>
using namespace std;

int main() {
    int N, M, K;
    cin >> N >> M >> K;
    vector<vector<pair<int,int>>> g(2 * N);  // (to, cost) cost: 0=翻转开关,1=Move
    auto add = [&](int u, int v, int w) { g[u].push_back({v, w}); };

    for (int i = 0; i < M; i++) {
        int u, v, a; cin >> u >> v >> a;
        u--; v--;
        if (a == 1) {          // 初始可通行：态0 直接走
            add(u, v, 1); add(v, u, 1);
        } else {               // 初始不可通行：态1（翻过一次后）可走
            add(u + N, v + N, 1); add(v + N, u + N, 1);
        }
    }
    for (int i = 0; i < K; i++) {
        int s; cin >> s; s--;
        add(s, s + N, 0);      // 态0 → 态1（翻开关）
        add(s + N, s, 0);      // 态1 → 态0
    }

    const int INF = 1 << 29;
    vector<int> dist(2 * N, INF);
    deque<int> dq;
    dist[0] = 0; dq.push_front(0);
    while (!dq.empty()) {
        int v = dq.front(); dq.pop_front();
        for (auto [to, w] : g[v]) {
            if (dist[to] > dist[v] + w) {
                dist[to] = dist[v] + w;
                if (w == 0) dq.push_front(to);
                else dq.push_back(to);
            }
        }
    }
    int ans = min(dist[N - 1], dist[2 * N - 1]);
    cout << (ans >= INF ? -1 : ans) << '\n';
    return 0;
}

