#include <bits/stdc++.h>
using namespace std;

int main() {
    int N; long long D;
    cin >> N >> D;
    vector<pair<long long, long long>> wall(N);
    for (int i = 0; i < N; i++) cin >> wall[i].first >> wall[i].second;
    sort(wall.begin(), wall.end(), [](auto& a, auto& b) { return a.second < b.second; });

    long long ans = 0, covered_until = -1;  // 已覆盖的最右列（1-indexed 语义：被某拳打到的范围）
    for (auto [L, R] : wall) {
        if (L <= covered_until) continue;   // 已被之前某拳覆盖
        ans++;                              // 新打一拳：以当前墙右端点 R 为中心向 D 宽覆盖
        covered_until = R + D - 1;
    }
    cout << ans << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    int N; cin >> N;
    vector<string> S(N), T(N);
    map<string, string> nxt;
    for (int i = 0; i < N; i++) { cin >> S[i] >> T[i]; nxt[S[i]] = T[i]; }

    // DFS 判环：白/灰/黑三色。有向边 S -> T。若成环 → No
    map<string, int> color;  // 0 未访问, 1 在栈中, 2 完成
    bool cycle = false;
    function<void(string)> dfs = [&](string u) {
        color[u] = 1;
        auto it = nxt.find(u);
        if (it != nxt.end()) {
            string v = it->second;
            int c = color[v];
            if (c == 0) dfs(v);
            else if (c == 1) cycle = true;
        }
        color[u] = 2;
    };
    for (auto& [s, _] : nxt) {
        if (color[s] == 0) dfs(s);
    }
    cout << (cycle ? "No" : "Yes") << '\n';
    return 0;
}

