using namespace std;

ll N = 1e18;
ll MOD = 1e9 + 7;

ll number_of_sh_paths(vector<ll> graph[],ll n){
	priority_queue<pair<ll,ll>,vector<pair<ll,ll>>,greater<pair<ll,ll>>> pq;
	pq.push({0,1});
	vector<ll> ways(n,0),dist(n,N);
	dist[1] = 0;
	ways[1] = 1;
	while(!pq.empty()){
		ll node = pq.top().second;
		pq.pop();
		for(auto val:graph[node]){
			if(dist[val] > dist[node] + 1){
				dist[val] = dist[node] + 1;
				pq.push({dist[val],val});
				ways[val] = ways[node];
			}else if(dist[val] == dist[node] + 1){
				ways[val] = (ways[val] + ways[node]) % MOD;
			}
		}
	}
	return ways[n - 1] % MOD;
}

