    s[1] = 0;
    q.push(1);
    while (!q.empty()) {
        long long x = q.front();
        q.pop();

        long long y = x * a;
        if (y < pow10[md] && s[y] > s[x] + 1) {
            s[y] = s[x] + 1;
            q.push(y);
        }

        if (x > 10 && x % 10 != 0) {
            int d = upper_bound(pow10.begin(), pow10.end(), x) - pow10.begin() - 1;
            y = x / 10 + (x % 10) * pow10[d];
            if (s[y] > s[x] + 1) {
                s[y] = s[x] + 1;
                q.push(y);
            }
        }
    }

    if (s[n] == 1e9) {
        s[n] = -1;
    }

