#define int long long

constexpr int N = 1e6 + 5;
vector<bool> is_prime(N, true); 
vector<int> primes;
void NaiveSieve(long long n) {
    is_prime[0] = is_prime[1] = false;
    for (long long i = 2; i <= n; i++) {
        if (is_prime[i]) {
            primes.push_back(i);
            for (long long j = i + i; j <= n; j += i) {
                is_prime[j] = false;  
            }
        }
    }
}

void solve() {
    int n; cin >> n;
    int ans = 0;
    for (auto q : primes) {
        __int128_t cur = q * q * q;
        if (2 * cur > n) break;
        int l = 2, r = 1e18, i = q - 1;
        while (l <= r) {
            int mid = l + (r - l) / 2;
            __int128_t t = mid * cur;
            if (t <= n) {
                l = mid + 1;
                i = min(mid, q - 1);
            } else {
                r = mid - 1;
            }
        } 
        if (i and i < q) {
            auto it = upper_bound(begin(primes), end(primes), i);
            if (it != primes.begin()) {
                ans += it - begin(primes);
            }
        }
    }
    cout << ans;
}

