using namespace std;

int N, T, M;
bool conflict[12][12];          // conflict[a][b] = a,b 不能同组
vector<int> team;
long long ans = 0;

void dfs(int k, int groups) {
    if (k == N) {
        if (groups == T) ans++;
        return;
    }
    // 组无标号去重：第 k 人只能加入编号 <= min(groups, T-1) 的组
    for (int g = 0; g <= min(groups, T - 1); g++) {
        bool ok = true;
        for (int p = 0; p < k; p++) {
            if (team[p] == g && conflict[k][p]) { ok = false; break; }
        }
        if (!ok) continue;
        team[k] = g;
        dfs(k + 1, max(groups, g + 1));
        team[k] = -1;
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> N >> T >> M;
    for (int i = 0; i < M; i++) {
        int a, b; cin >> a >> b; a--; b--;
        conflict[a][b] = conflict[b][a] = true;
    }
    team.assign(N, -1);
    dfs(0, 0);
    cout << ans << '\n';
    return 0;
}

