bool can(vector<int> a, int target) {
    int sum = 0;
    for(int x : a) sum += x;

    if(abs(target) > sum) return false;
    if((sum + target) % 2 != 0) return false;

    int need = (sum + target) / 2;
    vector<bool> dp(need + 1, false);
    dp[0] = true;

    for(int x : a) {
        for(int j = need; j >= x; --j) {
            if(dp[j - x]) dp[j] = true;
        }
    }
    return dp[need];
}

