struct Point
{
	int x, y;
};

int main()
{
	// 行数（高さ）と列数（幅）
	int R, C;
	std::cin >> R >> C;

	// フィールドの情報を読み込む
	std::vector<std::string> grid(R);
	for (auto& row : grid)
	{
		std::cin >> row;
	}

	// スタート・ゴールの座標を探す
	Point start;
	Point goal;

	for (int y = 0; y < R; ++y)
	{
		for (int x = 0; x < C; ++x)
		{
			if (grid[y][x] == 'S')
			{
				start = { x, y };
			}
			else if (grid[y][x] == 'G')
			{
				goal = { x, y };
			}
		}
	}

	// 人の視線に入っているか
	std::vector<std::vector<bool>> watched(R, std::vector<bool>(C));

	// 視線の構築
	for (int y = 0; y < R; ++y)
	{
		for (int x = 0; x < C; ++x)
		{
			const char current = grid[y][x];

			// 人が向いている方向
			Point direction;

			if (current == '>')
			{
				direction = { 1, 0 };
			}
			else if (current == '<')
			{
				direction = { -1, 0 };
			}
			else if (current == '^')
			{
				direction = { 0, -1 };
			}
			else if (current == 'v')
			{
				direction = { 0, 1 };
			}
			else
			{
				continue;
			}

			Point next{ (x + direction.x), (y + direction.y) };

			for (;;)
			{
				// 範囲外なら終了
				if ((next.x < 0) || (C <= next.x) || (next.y < 0) || (R <= next.y))
				{
					break;
				}

				// '.' 以外なら視線はそこで止まる
				if (grid[next.y][next.x] != '.')
				{
					break;
				}

				watched[next.y][next.x] = true;
				next.x += direction.x;
				next.y += direction.y;
			}
		}
	}

	std::vector<std::vector<int>> distances(R, std::vector<int>(C, -1));
	std::queue<Point> q;

	distances[start.y][start.x] = 0;
	q.push(start);

	// 上下左右の移動
	const std::vector<Point> directions{ {0, -1}, {0, 1}, {-1, 0}, {1, 0} };

	while (!q.empty())
	{
		const Point current = q.front();
		q.pop();

		for (const auto& direction : directions)
		{
			const Point next{ (current.x + direction.x), (current.y + direction.y) };

			// 範囲外の場合はスキップ
			if ((next.x < 0) || (C <= next.x) || (next.y < 0) || (R <= next.y))
			{
				continue;
			}

			// 通路・スタート・ゴール以外はスキップ
			if ((grid[next.y][next.x] != '.') &&
				(grid[next.y][next.x] != 'S') &&
				(grid[next.y][next.x] != 'G'))
			{
				continue;
			}

			// 人の視線に入っている場合はスキップ
			if (watched[next.y][next.x])
			{
				continue;
			}

			// 訪問済みの場合はスキップ
			if (distances[next.y][next.x] != -1)
			{
				continue;
			}

			distances[next.y][next.x] = (distances[current.y][current.x] + 1);
			q.push(next);
		}
	}

	std::cout << distances[goal.y][goal.x] << '\n';
}

