ll mul(ll a, ll b, ll mod) {
    ll res = 0;
    a %= mod;
    for (; b; b >>= 1) {
        if (b & 1) res = (res + a) % mod;
        a = (a + a) % mod;
    }
    return res;
}
ll qpow(ll b, ll exp, ll mod) {
    ll res = 1;
    b %= mod;
    for (; exp; exp >>= 1) {
        if (exp & 1) {
            res = mul(res, b, mod);
        }
        b = mul(b, b, mod);
    }
    return res;
}
int F(int x) {
    return x == f[x] ? x : (f[x] = F(f[x]));
}
