        for (int j = i + 1; j <= n; ++j) {
            ll v1 = qpow(a[i], a[j], m);
            ll v2 = qpow(a[j], a[i], m);
            d[i][j] = d[j][i] = (v1 + v2) % m;
            e.emplace_back(i, j);
        }
    }
    sort(e.begin(), e.end(), [](const pii& x, const pii& y) {
        return d[x.first][x.second] > d[y.first][y.second];
