#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int H, W, T;
    cin >> H >> W >> T;
    vector<string> A(H);
    for (int i = 0; i < H; i++) cin >> A[i];

    const int INF = 1e9;
    int dirs[4][2] = {{0,1},{0,-1},{1,0},{-1,0}};
    auto bfs = [&](int sr, int sc) {
        vector<vector<int>> d(H, vector<int>(W, INF));
        queue<pair<int,int>> q;
        d[sr][sc] = 0;
        q.push({sr, sc});
        while (!q.empty()) {
            auto [r, c] = q.front(); q.pop();
            for (auto& dd : dirs) {
                int nr = r + dd[0], nc = c + dd[1];
                if (nr < 0 || nr >= H || nc < 0 || nc >= W) continue;
                if (A[nr][nc] == '#' || d[nr][nc] != INF) continue;
                d[nr][nc] = d[r][c] + 1;
                q.push({nr, nc});
            }
        }
        return d;
    };

    int sy = 0, sx = 0, gy = 0, gx = 0;
    vector<pair<int,int>> candies;
    for (int i = 0; i < H; i++) for (int j = 0; j < W; j++) {
        if (A[i][j] == 'S') { sy = i; sx = j; }
        if (A[i][j] == 'G') { gy = i; gx = j; }
        if (A[i][j] == 'o') candies.push_back({i, j});
    }

    auto dS = bfs(sy, sx);
    if (dS[gy][gx] > T) { cout << -1 << '\n'; return 0; }

    int n = candies.size();
    vector<pair<int,int>> all;
    all.push_back({sy, sx});
    for (auto& c : candies) all.push_back(c);
    all.push_back({gy, gx});
    // D[i][j] = 关键点 i 到 j 的最短距离（0=S, 1..n=糖果, n+1=G）
    vector<vector<int>> D(n + 2, vector<int>(n + 2, INF));
    for (int i = 0; i < n + 2; i++) {
        auto d = bfs(all[i].first, all[i].second);
        for (int j = 0; j < n + 2; j++)
            D[i][j] = d[all[j].first][all[j].second];
    }

    // 状压 DP：dp[mask][last] 访问糖果集 mask 后停在 last 的最短长度（从 S 出发）
    int best = -1;
    vector<vector<int>> dp(1 << n, vector<int>(n, INF));
    for (int i = 0; i < n; i++) dp[1 << i][i] = D[0][i + 1];
    for (int mask = 1; mask < (1 << n); mask++) {
        for (int last = 0; last < n; last++) {
            if (!(mask >> last & 1) || dp[mask][last] >= INF) continue;
            if (dp[mask][last] + D[last + 1][n + 1] <= T)
                best = max(best, __builtin_popcount(mask));
            for (int nxt = 0; nxt < n; nxt++) {
                if (mask >> nxt & 1) continue;
                dp[mask | (1 << nxt)][nxt] =
                    min(dp[mask | (1 << nxt)][nxt],
                        dp[mask][last] + D[last + 1][nxt + 1]);
            }
        }
    }
    cout << best << '\n';
    return 0;
}

