const ll MOD = 998244353;

ll modpow(ll a, ll e) {
    ll r = 1;
    while (e) { if (e & 1) r = r * a % MOD; a = a * a % MOD; e >>= 1; }
    return r;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int N, X;
    cin >> N >> X;
    vector<int> T(N);
    for (int i = 0; i < N; i++) cin >> T[i];

    ll invN = modpow(N, MOD - 2);
    // dp[t] = 时刻 t 恰好开始播放某首歌的概率
    vector<ll> dp(X + 2, 0);
    dp[0] = 1;
    for (int t = 1; t <= X; t++) {
        ll s = 0;
        for (int i = 0; i < N; i++)
            if (t - T[i] >= 0) s = (s + dp[t - T[i]]) % MOD;
        dp[t] = s * invN % MOD;
    }
    // song1 在 (X+0.5) 秒播放 ⟺ 在 [X+1-T1, X] 内开始 song1
    ll ans = 0;
    for (int s = max(0, X + 1 - T[0]); s <= X; s++)
        ans = (ans + dp[s]) % MOD;
    ans = ans * invN % MOD;
    cout << ans << '\n';
    return 0;
}

