const ll MOD = 998244353;
const ll INF = 1e18;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    ll n, k, q; cin >> n >> k >> q;

    ll sm = 0;
    vector<bool> is_included (n);
    vector<ll> a (n, 0);
    priority_queue<pll> not_included;
    priority_queue<pll, vector<pll>, greater<pll>> included;

    for (int i=0; i<k; i++) {
        included.push({0, i});
        is_included[i] = true;
    }
    for (int i=k; i<n; i++) {
        not_included.push({0, i});
        is_included[i] = false;
    }

    auto top_included = [&]() {
        while (!included.empty()) {
            auto [v, idx] = included.top();
            if (a[idx] == v && is_included[idx]) return (pll){v,idx};
            included.pop();
        }
        return (pll){INF, n};
    };
    auto top_not_included = [&]() {
        while (!not_included.empty()) {
            auto [v, idx] = not_included.top();
            if (a[idx] == v && !is_included[idx]) return (pll){v,idx};
            not_included.pop();
        }
        return (pll){-INF, n};
    };

    while (q--) {
        ll i, x; cin >> i >> x; i--;

        if (is_included[i]) {
            auto [y, j] = top_not_included();
            if (x < y) {
                swap(is_included[i], is_included[j]);

                not_included.pop();
                not_included.push({x,i});
                included.push({y,j});
                sm += a[j] - a[i];
            } else {
                included.push({x,i});
                sm += x - a[i];
            }
        } else {
            auto [y, j] = top_included();
            if (y < x) {
                swap(is_included[i], is_included[j]);

                not_included.push({y,j});
                included.pop();
                included.push({x,i});
                sm += x - a[j];
            } else {
                not_included.push({x,i});
            }
        }
        a[i] = x;

        cout << sm << endl;
    }
}

