#include <iostream>
#include <vector>

using namespace std;

void search(int x, int n, int h, int &ans, const vector<vector<int>> &a, vector<bool> &b) {
    if (x == n - 1) {
        ans = max(ans, h);
        return;
    }
    
    if (b[x]) {
        search(x + 1, n, h, ans, a, b);
        return;
    }
    
    b[x] = true;
    
    for (int y = x + 1; y < n; y++) {
        if (b[y]) {
            continue;
        }
        
        b[y] = true;
        search(x + 1, n, h ^ a[x][y - x - 1], ans, a, b);
        b[y] = false;
    }
    
    b[x] = false;
}

