int nums[20];

int get_len(void)
{
    int res = 0;
    int num = n;
    while(num>0)
    {
        res++;
        nums[res] = num%10;
        num /= 10;
    }
    reverse(nums+1,nums+res+1);
    return res;
}

signed main(void)
{
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n;
    len = get_len();

    int res = 0;
    for(int fsum=1;fsum<=9*len;fsum++)
    {
        memset(dp,0,sizeof(dp));

        int op=1;
        dp[op][0][0][1] = 1;
        
        //采取推的写法
        for(int i=0;i<=len-1;i++)
        {
            int nop = op^1;
            memset(dp[nop],0,sizeof(dp[nop]));

            //先处理k=0的情况，随便放
            for(int j=0;j<fsum;j++) //枚举余数
            {
                for(int Now=0;Now<=9;Now++) //枚举下一位要放的数
                {
                    for(int sum=0;sum<=fsum;sum++) //枚举已经有的数字总和
                    {
                        int nr = (j*10+Now)%fsum;
                        int nsum = sum+Now;
                        if(nsum>fsum) break;
                        dp[nop][nr][nsum][0] += dp[op][j][sum][0];
                    }
                }
            }

            //再处理k=1的情况
            for(int j=0;j<fsum;j++)
            {
                for(int Now=0;Now<nums[i+1];Now++)
                {
                    for(int sum=0;sum<=fsum;sum++) //枚举已经有的数字总和
                    {
                        int nr = (j*10+Now)%fsum;
                        int nsum = sum+Now;
                        if(nsum>fsum) break;
                        dp[nop][nr][nsum][0] += dp[op][j][sum][1];
                    }
                }
                int Num = nums[i+1];
                int nr = (j*10+Num)%fsum;
                for(int sum=0;sum<=fsum;sum++) //枚举已经有的数字总和
                {
                    int nsum = sum+Num;
                    if(nsum>fsum) break;
                    dp[nop][nr][nsum][1] += dp[op][j][sum][1];
                }
            }
            op = nop;
        }

        int ans = dp[op][0][fsum][0]+dp[op][0][fsum][1];
        res += ans;
    }

    cout << res << endl;

    return 0;
}

