    int startR, startC;
    int targetR, targetC;
    for(int r = 0; r<H ; r++)
        for(int c = 0 ; c<W; c++){
            cin>>A[r][c];
            if(A[r][c]=='S')
                startR = r, startC = c;
            if(A[r][c]=='T')
                targetR = r, targetC = c;
        }
    
    cin>>N;
    int R, C , E;
    for(int i = 0 ; i<N ; i++ ) {
        cin>>R>>C>>E;
        M[R-1][C-1]=E;
    }
    if(startR==targetR && startC==targetC) {
        cout<<"Yes"<<endl;
        return 0;
    }
    if(M[startR][startC]==0) {
        cout<<"No"<<endl;
        return 0;
    };

    auto checkBounds = [&](int r, int c) -> bool{
        if(r<0 || r>=H || c<0 || c>=W) return false;
        return true;
    };

    vector<int> visited(H*W,-1);
    queue<pair<int,int>> q;
    vector<pair<int,int>> drc{{0,1},{0,-1},{1,0},{-1,0}};
    visited[startR*W+startC] = 0;
    q.push({startR*W+startC,0});

    while(!q.empty()){
        auto [cell,energy] = q.front();
        q.pop();
        int r = cell/W;
        int c = cell%W;
        if(r==targetR && c==targetC) {
            cout<<"Yes"<<endl;
            return 0;
        }
        energy = max(energy,M[r][c]);
        if(energy==0) continue;
        for(auto& [dr,dc] : drc){
            int R = r+dr;
            int C = c+dc;
            if(checkBounds(R,C)==false) continue;
            if (A[R][C] == '#') continue;
            if(visited[R*W+C]<energy-1){
                q.push({R*W+C,energy-1});
                visited[R*W+C]=energy-1;
            }
        }
    }

    cout<<"No"<<endl;
    return 0;
}

