#include <bits/stdc++.h>
using namespace std ;
using i64 = long long ;
using Matrix = array<array<int, 2>, 2> ;
const int Modulus = 998244353 ;

int digit_width(i64 n){
    if(not n) return 1 ;

    int cnt{} ;
    while(n){
        ++cnt ;
        n /= 10 ;
    }

    return cnt ;
}

Matrix operator*(const Matrix &m1, const Matrix &m2){
    Matrix ans{} ;
    for(int i{}; i < 2; ++i)
        for(int j{}; j < 2; ++j)
            for(int k{}; k < 2; ++k)
                ans[i][j] = (ans[i][j] + i64(m1[i][k]) * m2[k][j]) % Modulus ;

    return ans ;
}

int f(i64 n){
    i64 exp{n} ;
    int d{digit_width(n)}, k{1} ;
    for(int i{}; i < d; ++i)
        k = (k * 10LL) % Modulus ;

    Matrix res{}, trans{} ;
    trans[0][0] = k ;
    for(int i{}; i < 2; ++i){
        trans[1][i] = 1 ;
        res[i][i] = 1 ;
    }

    while(exp){
        if(exp & 1) res = res * trans ;
        trans = trans * trans ;
        exp >>= 1 ;
    }

    n %= Modulus ;
    return (n * res[1][0]) % Modulus ;
}

