// 繰り返し二乗法(mod計算なし)
long long pow_ll(long long a, long long n)
{
    long long ans = 1;
    long long kake = a;
    while (n > 0)
    {
        if (n % 2)
            ans *= kake;
        kake *= kake;
        n /= 2;
    }
    return ans;
}

// 繰り返し二乗法(mod計算あり)
long long pow_ll_mod(long long a, long long n, long long m)
{
    long long ans = 1;
    long long kake = a;
    while (n > 0)
    {
        if (n % 2)
            ans = ((ans % m) * (kake % m)) % m;
        kake = ((kake % m) * (kake % m)) % m;
        n /= 2;
    }
    return ans;
}

// 組み合わせの総数計算
long long combination(long long n, long long r)
{
    if (n < r || n < 0 || r < 0)
        return 0;
    if (r > n / 2)
        r = n - r;
    long long ans = 1, j = 1;
    for (long long i = n; i >= n - r + 1; i--)
    {
        ans *= i;
        ans /= j;
        j++;
    }
    return ans;
}

// 約数列挙
set<long long> divisor(long long n)
{
    set<long long> ans;
    for (long long i = 1; i * i <= n; i++)
    {
        if (n % i == 0)
        {
            ans.insert(i);
            ans.insert(n / i);
        }
    }
    return ans;
}

