void solve(){
    int n;
    cin >> n;
    vector<int> a(n+1);
    vector<int> b(n+1);
    int sum = 0;
    for(int i = 1; i <= n; i++){
        cin >> a[i] >> b[i];
        sum += b[i];
    }
    
    if(sum % 3 != 0){
        cout << -1 << '\n';
        return;
    }
    
    int now = sum / 3;
    
    // 【修改点1】：去掉最外面的 i 维度，只开二维数组。
    // 这代表“上一层（前 i-1 个人）”的状态
    vector<vector<int>> dp(now + 1, vector<int>(now + 1, 1e18));
    dp[0][0] = 0;
    
    int curr = 0;
    
    for(int i = 1; i <= n; i++){
        int team = a[i];
        int po = b[i];
        
        // 【修改点2】：在这个循环里建一个新数组 ndp（全都初始化为 1e18）
        // 它代表加入“当前第 i 个人”后的新状态
        vector<vector<int>> ndp(now + 1, vector<int>(now + 1, 1e18));
        
        for(int j = 0; j <= now; j++){
            for(int k = 0; k <= now; k++){
                
                // 注意这里查的是 dp，即上一层的旧状态
                if(dp[j][k] != 1e18){
                    
                    // --- 选择 1 ---
                    // 更新到 ndp 里（新状态）
                    if(po + j <= now){
                        int cost = (team != 1) ? 1 : 0;
                        ndp[j + po][k] = min(ndp[j + po][k], dp[j][k] + cost);
                    }
                    
                    // --- 选择 2 ---
                    if(po + k <= now){
                        int cost = (team != 2) ? 1 : 0;
                        ndp[j][k + po] = min(ndp[j][k + po], dp[j][k] + cost);
                    }
                    
                    // --- 选择 3 ---
                    int c = curr - j - k;
                    if(c + po <= now){
                        int cost = (team != 3) ? 1 : 0;
                        ndp[j][k] = min(ndp[j][k], dp[j][k] + cost);
                    }
                }
            }
        }
        
        curr += po;
        
        // 【修改点3】！关键操作：滚动！
        // 把计算好的新状态 ndp，直接赋值覆盖掉老状态 dp
        // 下一个人循环时，现在的 ndp 就变成了前一个人的状态
        dp = ndp; 
    }
    
    // 最终直接输出 dp[now][now] 即可，不需要带上维度 n 了
    if(dp[now][now] != 1e18){
        cout << dp[now][now] << '\n';
    } else {
        cout << -1 << '\n';
    }
}

