    vector<vector<bool>> seen(h + 2, vector<bool> (w + 2, false));
    priority_queue<pair<ll, pair<int, int>>, vector<pair<ll, pair<int, int>>>, greater<pair<ll, pair<int, int>>>> bfs;
    for(int i = 1; i < h + 1; i++){
        for(int j = 1; j < w + 1; j++){
            cin >> s[i][j];
        }
    }
    int nx[4] = {1, 0, -1, 0}, ny[4] = {0, 1, 0, -1};
    ll taka = s[p][q];
    seen[p][q] = true;
    for(int i = 0; i < 4; i++){
        if(s[p + nx[i]][q + ny[i]] != -1){
            bfs.push({s[p + nx[i]][q + ny[i]], {p + nx[i], q + ny[i]}});
            seen[p + nx[i]][q + ny[i]] = true;
        }
    }
    pair<ll, pair<int, int>> tmp = bfs.top();
    ll a = tmp.first;
    int b = tmp.second.first;
    int c = tmp.second.second;
    while(bfs.size() != 0 && a < (taka % x != 0 ? taka / x + 1 : taka / x)){
        bfs.pop();
        taka += a;
        int mx[4] = {1, 0, -1, 0}, my[4] = {0, 1, 0, -1};
        for(int i = 0; i < 4; i++){
            mx[i] += b; my[i] += c;
            if(seen[mx[i]][my[i]] == false && s[mx[i]][my[i]] != -1){
                seen[mx[i]][my[i]] = true;
                bfs.push({s[mx[i]][my[i]], {mx[i], my[i]}});
            }
        }
        if(bfs.size() != 0){
            pair<ll, pair<int, int>> tmp = bfs.top();
            a = tmp.first;
            b = tmp.second.first;
            c = tmp.second.second;
        }else{
            break;
        }
    }
    cout << taka << endl;
    return 0;
}

